result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "jsv.py", "content": """"jsv.py -- a minimal-but-useful-core JSON Schema validator.

Public API:
    validate(schema, instance) -> list[dict]

Each error dict has the shape::

    {"path": <str>, "keyword": <str>, "message": <str>}

Paths use JSON-pointer-ish syntax relative to the document root, e.g.
"/users/3/email". The root itself is the empty string "".

Supported keywords:
    type                  ("string" | "number" | "integer" | "boolean" |
                           "object" | "array" | "null")
    properties, required, additionalProperties (False or a schema)
    items                 (single-schema form)
    enum
    minimum, maximum, exclusiveMinimum, exclusiveMaximum
    minLength, maxLength, pattern         (Python re.search semantics)
    minItems, maxItems, uniqueItems

Documented choices / edge cases:
  * Booleans are NOT integers (nor numbers): ``True`` fails {"type": "integer"}
    and {"type": "number"}; ``1`` fails {"type": "boolean"}.
  * "integer" accepts Python ints only (no floats, no bools); "number"
    accepts int and float.
  * Equality everywhere (``enum`` membership and ``uniqueItems``) follows
    JSON semantics: two values are equal iff they have the same JSON type
    and compare equal under Python ``==``. Concretely ``1 == 1.0`` (both
    JSON numbers), so [1, 1.0] violates uniqueItems; but ``True`` is never
    equal to ``1`` because boolean is a distinct JSON type.
  * If the "type" keyword fails, child keywords are not evaluated for that
    node (they would mostly be noise); everything else collects all errors,
    depth-first.
"""

import re

__all__ = ["validate"]


# ---------------------------------------------------------------- helpers

def _is_number(value):
    """JSON number: int or float, excluding bool."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _is_integer(value):
    """JSON integer: int only, excluding bool."""
    return isinstance(value, int) and not isinstance(value, bool)


_TYPE_CHECKS = {
    "object": lambda v: isinstance(v, dict),
    "array": lambda v: isinstance(v, list),
    "string": lambda v: isinstance(v, str),
    "boolean": lambda v: isinstance(v, bool),
    "integer": _is_integer,
    "number": _is_number,
    "null": lambda v: v is None,
}


def _json_equal(a, b):
    """JSON-semantics equality (see module docstring)."""
    if isinstance(a, bool) != isinstance(b, bool):
        return False
    return a == b


def _child(path, key):
    return "{}/{}".format(path, key)


# ------------------------------------------------------------- validation

def validate(schema, instance):
    errors = []
    _validate(schema, instance, "", errors)
    return errors


def _validate(schema, instance, path, errors):

    def fail(keyword, message):
        errors.append({"path": path, "keyword": keyword, "message": message})

    # ---- enum ----
    if "enum" in schema:
        if not any(_json_equal(choice, instance) for choice in schema["enum"]):
            fail("enum", "value {!r} is not one of {!r}".format(instance, schema["enum"]))

    # ---- type ----
    if "type" in schema:
        expected = schema["type"]
        check = _TYPE_CHECKS.get(expected)
        if check is None:
            fail("type", "schema has unknown type {!r}".format(expected))
            return
        if not check(instance):
            fail("type", "expected type {!r}, got {!r}".format(expected, type(instance).__name__))
            return  # child keywords would be noise on the wrong type

    # ---- numeric ----
    if _is_number(instance):
        if "minimum" in schema and instance < schema["minimum"]:
            fail("minimum", "value {!r} is less than minimum {!r}".format(instance, schema["minimum"]))
        if "maximum" in schema and instance > schema["maximum"]:
            fail("maximum", "value {!r} is greater than maximum {!r}".format(instance, schema["maximum"]))
        if "exclusiveMinimum" in schema and instance <= schema["exclusiveMinimum"]:
            fail("exclusiveMinimum",
                 "value {!r} is not greater than exclusiveMinimum {!r}".format(instance, schema["exclusiveMinimum"]))
        if "exclusiveMaximum" in schema and instance >= schema["exclusiveMaximum"]:
            fail("exclusiveMaximum",
                 "value {!r} is not less than exclusiveMaximum {!r}".format(instance, schema["exclusiveMaximum"]))

    # ---- string ----
    if isinstance(instance, str):
        if "minLength" in schema and len(instance) < schema["minLength"]:
            fail("minLength", "string of length {} is shorter than minLength {}".format(len(instance), schema["minLength"]))
        if "maxLength" in schema and len(instance) > schema["maxLength"]:
            fail("maxLength", "string of length {} is longer than maxLength {}".format(len(instance), schema["maxLength"]))
        if "pattern" in schema and re.search(schema["pattern"], instance) is None:
            fail("pattern", "string {!r} does not match pattern {!r}".format(instance, schema["pattern"]))

    # ---- array ----
    if isinstance(instance, list):
        if "minItems" in schema and len(instance) < schema["minItems"]:
            fail("minItems", "array of {} item(s) has fewer than minItems {}".format(len(instance), schema["minItems"]))
        if "maxItems" in schema and len(instance) > schema["maxItems"]:
            fail("maxItems", "array of {} item(s) has more than maxItems {}".format(len(instance), schema["maxItems"]))
        if schema.get("uniqueItems"):
            for i in range(len(instance)):
                for j in range(i + 1, len(instance)):
                    if _json_equal(instance[i], instance[j]):
                        fail("uniqueItems", "items at {} and {} are duplicates ({!r})".format(i, j, instance[i]))
                        break  # one error per offending later item is enough
                else:
                    continue
                # no double-reporting the same pair set; stop scanning pairs
                # involving earlier indices for this item
                # (fall through so other items may also be reported once)
        if "items" in schema:
            item_schema = schema["items"]
            for i, item in enumerate(instance):
                _validate(item_schema, item, _child(path, i), errors)

    # ---- object ----
    if isinstance(instance, dict):
        for prop in schema.get("required", []):
            if prop not in instance:
                fail("required", "required property {!r} is missing".format(prop))
        for prop, subschema in schema.get("properties", {}).items():
            if prop in instance:
                _validate(subschema, instance[prop], _child(path, prop), errors)
        if "additionalProperties" in schema:
            allowed = schema.get("properties", {})
            extra = schema.get("additionalProperties")
            for prop in instance:
                if prop in allowed:
                    continue
                if extra is False:
                    fail("additionalProperties", "additional property {!r} is not allowed".format(prop))
                elif isinstance(extra, dict):
                    _validate(extra, instance[prop], _child(path, prop), errors)
"})
