from jsv import validate


# ------------------------------------------------------- compliance test

SCHEMA = {
    "type": "object",
    "required": ["users"],
    "properties": {
        "users": {
            "type": "array",
            "minItems": 2,
            "items": {
                "type": "object",
                "required": ["id", "email"],
                "properties": {
                    "id": {"type": "integer", "minimum": 1},
                    "email": {"type": "string", "pattern": "^[^@]+@[^@]+$"},
                    "role": {"enum": ["admin", "user"]},
                },
                "additionalProperties": False,
            },
        },
        "version": {"type": "number", "exclusiveMaximum": 3},
    },
}

# Violates exactly 7 different keywords:
#   1. required      -> "users" missing? No: keep "users", drop nothing...
# We violate: minimum, pattern, enum, required, additionalProperties,
#             exclusiveMaximum, type
INSTANCE = {
    "users": [
        {   # index 0: fully valid anchor user
            "id": 1,
            "email": "a@example.com",
            "role": "admin",
        },
        {   # index 1: violates minimum (id), pattern (email),
            #          enum (role), additionalProperties (boss_mode)
            "id": 0,
            "email": "not-an-email",
            "role": "superadmin",
            "boss_mode": True,
        },
        {   # index 2: violates required (missing email)
            "id": 7,
        },
    ],
    "version": 5,   # violates exclusiveMaximum (5 >= 3)
}

EXPECTED = [
    {"path": "/users/1/id", "keyword": "minimum"},
    {"path": "/users/1/email", "keyword": "pattern"},
    {"path": "/users/1/role", "keyword": "enum"},
    {"path": "/users/1/boss_mode", "keyword": "additionalProperties"},
    {"path": "/users/2", "keyword": "required"},
    {"path": "/version", "keyword": "exclusiveMaximum"},
]


def test_compliance_seven_errors_exact():
    errors = validate(SCHEMA, INSTANCE)
    assert len(errors) == 7, errors
    got = [{"path": e["path"], "keyword": e["keyword"]} for e in errors]
    assert got == EXPECTED


# --------------------------------------------- True / 1 type distinction

def test_true_fails_integer():
    errs = validate({"type": "integer"}, True)
    assert errs == [{"path": "", "keyword": "type", "message": errs[0]["message"]}]


def test_one_passes_integer():
    assert validate({"type": "integer"}, 1) == []


def test_one_fails_boolean():
    errs = validate({"type": "boolean"}, 1)
    assert errs == [{"path": "", "keyword": "type", "message": errs[0]["message"]}]


def test_true_passes_boolean():
    assert validate({"type": "boolean"}, True) == []


def test_bool_is_not_number_either():
    assert validate({"type": "number"}, False) != []
    assert validate({"type": "number"}, 1.5) == []


# ------------------------------------------- additionalProperties: False

def test_additional_properties_false_flags_intruder():
    schema = {"additionalProperties": False}
    errs = validate(schema, {"legit": 1, "intruder": 2})
    assert errs == [{
        "path": "/intruder",
        "keyword": "additionalProperties",
        "message": errs[0]["message"],
    }]


def test_additional_properties_as_schema_validates_value():
    schema = {"properties": {"a": {}}, "additionalProperties": {"type": "string"}}
    assert validate(schema, {"a": 1, "b": "ok"}) == []
    assert [e["keyword"] for e in validate(schema, {"b": 9})] == ["type"]
    assert [e["path"] for e in validate(schema, {"b": 9})] == ["/b"]


# ------------------------------------------------------------ uniqueItems

def test_unique_items_catches_int_and_float():
    # Documented choice: JSON equality treats 1 and 1.0 as equal numbers.
    assert validate({"uniqueItems": True}, [1, 1.0]) != []
    assert [e["keyword"] for e in validate({"uniqueItems": True}, [1, 1.0])] == ["uniqueItems"]


def test_unique_items_bool_never_equals_number():
    # Documented choice: True is of JSON type boolean, never equal to 1.
    assert validate({"uniqueItems": True}, [True, 1]) == []


def test_unique_items_allows_distinct_values():
    assert validate({"uniqueItems": True}, [1, 2, "a", None, [1], {"a": 1}]) == []
    assert validate({"uniqueItems": True}, [[1, 2], [1, 2]]) != []


# --------------------------------------------------- valid instance -> []

def test_fully_valid_instance_yields_empty_list():
    doc = {
        "users": [
            {"id": 1, "email": "a@example.com", "role": "admin"},
            {"id": 2, "email": "b@example.com", "role": "user"},
        ],
        "version": 2.5,
    }
    assert validate(SCHEMA, doc) == []


# ------------------------------------------------------ remaining keywords

def test_type_keyword_all_variants():
    ok = [("string", "x"), ("integer", 3), ("number", 3.5), ("boolean", False),
          ("object", {}), ("array", []), ("null", None)]
    for t, v in ok:
        assert validate({"type": t}, v) == [], (t, v)
        assert validate({"type": t}, "other-wrong") != []


def test_required_and_nested_paths():
    schema = {"properties": {"users": {"items": {"required": ["email"]}}}}
    errs = validate(schema, {"users": [{}, {}, {"email": "x"}]})
    assert [(e["path"], e["keyword"]) for e in errs] == [("/users/0", "required"), ("/users/1", "required")]


def test_min_max_length():
    schema = {"minLength": 2, "maxLength": 3}
    assert validate(schema, "ab") == []
    assert [(e["keyword"], e["path"]) for e in validate(schema, "a")] == [("minLength", "")]
    assert [(e["keyword"], e["path"]) for e in validate(schema, "abcd")] == [("maxLength", "")]


def test_pattern_uses_search_not_fullmatch():
    assert validate({"pattern": "b"}, "abc") == []
    assert validate({"pattern": "^b$"}, "abc") != []


def test_min_max_items():
    assert validate({"minItems": 1, "maxItems": 2}, [1]) == []
    assert [e["keyword"] for e in validate({"minItems": 1}, [])] == ["minItems"]
    assert [e["keyword"] for e in validate({"maxItems": 1}, [1, 2])] == ["maxItems"]


def test_enum_uses_json_equality():
    assert validate({"enum": [1]}, 1.0) == []
    assert validate({"enum": [1]}, True) != []


def test_minimum_maximum_bounds():
    schema = {"minimum": 1, "maximum": 10}
    assert validate(schema, 1) == [] and validate(schema, 10) == []
    assert [e["keyword"] for e in validate(schema, 0)] == ["minimum"]
    assert [e["keyword"] for e in validate(schema, 11)] == ["maximum"]


def test_exclusive_bounds():
    schema = {"exclusiveMinimum": 1, "exclusiveMaximum": 10}
    assert validate(schema, 1.0001) == [] and validate(schema, 9.999) == []
    assert [e["keyword"] for e in validate(schema, 1)] == ["exclusiveMinimum"]
    assert [e["keyword"] for e in validate(schema, 10)] == ["exclusiveMaximum"]


def test_items_single_schema_form_recurses_depth_first():
    schema = {"items": {"type": "integer"}}
    errs = validate(schema, [1, "x", 2, "y"])
    assert [(e["path"], e["keyword"]) for e in errs] == [("/1", "type"), ("/3", "type")]


def test_root_path_is_empty_string():
    errs = validate({"type": "string"}, 42)
    assert errs[0]["path"] == ""
"})
